function GoldBtn({ onClick, href, children, disabled = false }) {
  const base = {
    display: 'inline-flex',
    alignItems: 'center',
    gap: 10,
    padding: '13px 14px 13px 22px',
    background: disabled
      ? 'rgba(0,45,22,.6)'
      : 'linear-gradient(135deg,#d6a10f,#b88008)',
    border: disabled ? '1px solid rgba(255,255,255,.12)' : 'none',
    borderRadius: 999,
    color: disabled ? 'rgba(255,255,255,.3)' : '#182312',
    fontSize: 15,
    fontWeight: 800,
    cursor: disabled ? 'not-allowed' : 'pointer',
    fontFamily: 'inherit',
    textDecoration: 'none',
    transition: 'transform .2s, box-shadow .2s',
    boxShadow: disabled ? 'none' : '0 10px 32px rgba(214,161,15,.35)',
    opacity: disabled ? 0.45 : 1,
    pointerEvents: disabled ? 'none' : 'auto',
    whiteSpace: 'nowrap',
    position: 'relative',
    overflow: 'hidden',
  };
  const arrow = (
    <div
      style={{
        width: 32,
        height: 32,
        borderRadius: '50%',
        background: disabled ? 'rgba(255,255,255,.08)' : 'rgba(255,255,255,.3)',
        display: 'grid',
        placeItems: 'center',
        fontSize: 16,
        flexShrink: 0,
      }}
    >
      →
    </div>
  );
  const handlers = disabled
    ? {}
    : {
        onMouseEnter: (e) => {
          e.currentTarget.style.transform = 'translateY(-2px)';
          e.currentTarget.style.boxShadow = '0 20px 48px rgba(214,161,15,.45)';
        },
        onMouseLeave: (e) => {
          e.currentTarget.style.transform = 'none';
          e.currentTarget.style.boxShadow = '0 10px 32px rgba(214,161,15,.35)';
        },
        onMouseDown: (e) => (e.currentTarget.style.transform = 'scale(.97)'),
        onMouseUp: (e) =>
          (e.currentTarget.style.transform = 'translateY(-2px)'),
      };
  if (href && !disabled)
    return (
      <a
        href={href}
        target="_blank"
        rel="noopener noreferrer"
        style={base}
        {...handlers}
      >
        {children}
        {arrow}
      </a>
    );
  return (
    <button onClick={onClick} disabled={disabled} style={base} {...handlers}>
      {children}
      {arrow}
    </button>
  );
}

function ShimmerBtn({ onClick, style: s, children }) {
  const [hover, setHover] = useState(false);
  return (
    <button
      onClick={onClick}
      style={{
        ...s,
        position: 'relative',
        overflow: 'hidden',
        cursor: 'pointer',
        fontFamily: 'inherit',
        transition: 'transform .22s, box-shadow .22s',
      }}
      onMouseEnter={(e) => {
        setHover(true);
        e.currentTarget.style.transform = 'translateY(-5px)';
        e.currentTarget.style.boxShadow = '0 28px 60px rgba(0,0,0,.4)';
      }}
      onMouseLeave={(e) => {
        setHover(false);
        e.currentTarget.style.transform = 'none';
        e.currentTarget.style.boxShadow =
          s.boxShadow || '0 16px 36px rgba(0,0,0,.25)';
      }}
      onMouseDown={(e) =>
        (e.currentTarget.style.transform = 'translateY(-2px) scale(.98)')
      }
      onMouseUp={(e) => (e.currentTarget.style.transform = 'translateY(-5px)')}
      onTouchStart={(e) => (e.currentTarget.style.transform = 'scale(.97)')}
      onTouchEnd={(e) => (e.currentTarget.style.transform = 'none')}
    >
      {children}
      <div
        style={{
          position: 'absolute',
          inset: '-100% -60%',
          background:
            'linear-gradient(100deg,transparent 30%,rgba(255,255,255,.18),transparent 70%)',
          transform: hover
            ? 'translateX(100%) rotate(12deg)'
            : 'translateX(-100%) rotate(12deg)',
          transition: hover ? 'transform .65s ease' : 'none',
          pointerEvents: 'none',
        }}
      />
    </button>
  );
}

