// ─── SCREEN 3: PATHWAYS ───────────────────────────────────────────────────────
const PATHWAYS = [
  {
    icon: '💛',
    title: 'Financial Supporter',
    desc: 'Choose this pathway if you wish to support Pangu through a voluntary financial contribution.',
    note: 'Financial contributions are voluntary and do not guarantee employment, appointment, endorsement, preferential treatment, event access, contracts, or any political or commercial benefit.',
  },
  {
    icon: '🤝',
    title: 'Sponsor / Pangu 200',
    desc: 'Choose this pathway if you are an individual, business, or organisation interested in formal sponsorship or partnership opportunities under the Pangu 200 pathway.',
    note: 'Submitting this form expresses interest in sponsorship only. Sponsorship is subject to approval, package confirmation, and completion of the required process.',
  },
  {
    icon: '✋',
    title: 'Volunteer Supporter',
    desc: 'Choose this pathway if you wish to support Pangu by offering your time, skills, and practical assistance during approved party activities, events, or community engagement.',
    note: 'Volunteer support is unpaid and does not guarantee employment, allowances, transport, accommodation, meals, gifts, endorsement, appointment, or future paid engagement.',
  },
];

function ParticipationScreen({ onBack }) {
  const [agreed, setAgreed] = useState(false);
  const [ripple, setRipple] = useState(false);
  const [btnBounce, setBtnBounce] = useState(false);

  const handleCheck = (val) => {
    setAgreed(val);
    if (val) {
      setRipple(true);
      setTimeout(() => setRipple(false), 520);
      setTimeout(() => setBtnBounce(true), 60);
      setTimeout(() => setBtnBounce(false), 460);
    }
  };

  return (
    <div
      style={{
        minHeight: '100vh',
        padding:
          'clamp(72px,8vw,96px) clamp(16px,3vw,40px) clamp(32px,4vw,56px)',
        animation: 'pageIn .6s cubic-bezier(.18,.9,.2,1) both',
        position: 'relative',
        zIndex: 2,
      }}
    >
      <BackBtn onClick={onBack} />
      <div
        style={{
          maxWidth: 1100,
          margin: '0 auto',
          padding: 'clamp(26px,4vw,52px)',
          borderRadius: 34,
          background:
            'linear-gradient(145deg,rgba(0,88,42,.45),rgba(0,29,15,.7))',
          border: '1px solid rgba(255,255,255,.15)',
          backdropFilter: 'blur(20px)',
          boxShadow:
            '0 28px 80px rgba(0,0,0,.4), inset 0 1px 0 rgba(255,255,255,.1)',
        }}
      >
        <div style={{ marginBottom: 26 }}>
          <Logo subLabel="Participation Registration" />
        </div>
        <h2
          style={{
            fontSize: 'clamp(28px,4vw,54px)',
            fontWeight: 900,
            letterSpacing: '-.05em',
            lineHeight: 1.02,
            color: '#fff',
            marginBottom: 12,
          }}
        >
          Choose Your Participation Pathway
        </h2>
        <p
          style={{
            fontSize: 'clamp(14px,1.6vw,18px)',
            lineHeight: 1.6,
            color: 'rgba(255,255,255,.75)',
            marginBottom: 28,
            maxWidth: 760,
          }}
        >
          Please review the options below and select the pathway that best
          applies to you before continuing to registration.
        </p>

        {/* White pathway cards */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(3,1fr)',
            gap: 16,
            marginBottom: 28,
          }}
          className="path-grid"
        >
          {PATHWAYS.map((p, i) => (
            <div
              key={i}
              style={{
                position: 'relative',
                padding: '26px 22px 22px',
                borderRadius: 24,
                background:
                  'radial-gradient(circle at 92% 0%,rgba(214,161,15,.18),transparent 8rem), rgba(255,255,255,.96)',
                color: '#092514',
                minHeight: 260,
                overflow: 'hidden',
                border: '1px solid rgba(255,255,255,.55)',
                boxShadow: '0 14px 44px rgba(0,0,0,.18)',
                transition:
                  'transform .28s cubic-bezier(.18,.9,.2,1), box-shadow .28s, background .28s',
                animation: `cardCascade .55s cubic-bezier(.16,1,.3,1) ${
                  i * 0.12 + 0.1
                }s both`,
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform =
                  'translateY(-10px) scale(1.013)';
                e.currentTarget.style.boxShadow =
                  '0 32px 80px rgba(0,0,0,.3), 0 0 0 1px rgba(214,161,15,.35)';
                e.currentTarget.style.background =
                  'radial-gradient(circle at 92% 0%,rgba(214,161,15,.26),transparent 8rem), rgba(255,255,255,1)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'none';
                e.currentTarget.style.boxShadow = '0 14px 44px rgba(0,0,0,.18)';
                e.currentTarget.style.background =
                  'radial-gradient(circle at 92% 0%,rgba(214,161,15,.18),transparent 8rem), rgba(255,255,255,.96)';
              }}
              onMouseDown={(e) =>
                (e.currentTarget.style.transform =
                  'translateY(-4px) scale(1.006)')
              }
              onMouseUp={(e) =>
                (e.currentTarget.style.transform =
                  'translateY(-10px) scale(1.013)')
              }
              onTouchStart={(e) =>
                (e.currentTarget.style.transform = 'scale(.98)')
              }
              onTouchEnd={(e) => (e.currentTarget.style.transform = 'none')}
            >
              <div
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  height: 5,
                  background: 'linear-gradient(90deg,#d6a10f,#00823b)',
                  borderRadius: '24px 24px 0 0',
                }}
              />
              <div
                style={{
                  position: 'absolute',
                  width: 140,
                  height: 140,
                  right: -55,
                  bottom: -55,
                  borderRadius: '50%',
                  border: '28px solid rgba(0,88,42,.06)',
                }}
              />
              <div
                style={{
                  width: 44,
                  height: 44,
                  borderRadius: 13,
                  display: 'grid',
                  placeItems: 'center',
                  marginBottom: 14,
                  background: 'linear-gradient(135deg,#00582a,#00823b)',
                  fontSize: 22,
                  boxShadow: '0 8px 20px rgba(0,88,42,.28)',
                  position: 'relative',
                  zIndex: 2,
                }}
              >
                {p.icon}
              </div>
              <h3
                style={{
                  marginBottom: 10,
                  color: '#00582a',
                  fontSize: 'clamp(16px,1.7vw,21px)',
                  letterSpacing: '-.03em',
                  lineHeight: 1.1,
                  fontWeight: 800,
                  position: 'relative',
                  zIndex: 2,
                }}
              >
                {p.title}
              </h3>
              <p
                style={{
                  fontSize: 13,
                  lineHeight: 1.6,
                  color: 'rgba(9,37,20,.74)',
                  marginBottom: 10,
                  position: 'relative',
                  zIndex: 2,
                }}
              >
                <strong style={{ color: 'rgba(9,37,20,.85)' }}>
                  Choose this pathway
                </strong>{' '}
                {p.desc.replace('Choose this pathway if', 'if')}
              </p>
              <p
                style={{
                  fontSize: 12,
                  lineHeight: 1.55,
                  color: 'rgba(9,37,20,.56)',
                  position: 'relative',
                  zIndex: 2,
                }}
              >
                <strong style={{ color: 'rgba(9,37,20,.7)' }}>
                  Please note:
                </strong>{' '}
                {p.note}
              </p>
            </div>
          ))}
        </div>

        {/* Checkbox */}
        <label
          style={{
            display: 'flex',
            alignItems: 'flex-start',
            gap: 12,
            margin: '0 0 20px',
            color: 'rgba(255,255,255,.88)',
            fontSize: 'clamp(13px,1.4vw,15px)',
            lineHeight: 1.5,
            cursor: 'pointer',
          }}
        >
          <div style={{ position: 'relative', flexShrink: 0, marginTop: 1 }}>
            <input
              type="checkbox"
              checked={agreed}
              onChange={(e) => handleCheck(e.target.checked)}
              style={{
                width: 22,
                height: 22,
                accentColor: '#d6a10f',
                cursor: 'pointer',
                position: 'relative',
                zIndex: 1,
              }}
            />
            {ripple && (
              <div
                style={{
                  position: 'absolute',
                  inset: 0,
                  borderRadius: '50%',
                  border: '2px solid rgba(214,161,15,.75)',
                  animation: 'rippleOut .52s ease forwards',
                  pointerEvents: 'none',
                }}
              />
            )}
          </div>
          I have read and understood the participation pathways above and wish
          to continue to the registration form.
        </label>

        {/* CTA */}
        <div
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            alignItems: 'center',
            gap: 16,
          }}
        >
          <div
            style={{
              transition: 'transform .4s cubic-bezier(.34,1.56,.64,1)',
              transform: btnBounce ? 'scale(1.06)' : 'scale(1)',
            }}
          >
            {agreed ? (
              <GoldBtn href={PARTICIPATION_URL}>
                Continue to Registration
              </GoldBtn>
            ) : (
              <GoldBtn disabled>Continue to Registration</GoldBtn>
            )}
          </div>
          <span
            style={{
              color: 'rgba(255,255,255,.38)',
              fontSize: 13,
              transition: 'opacity .5s',
              opacity: agreed ? 0 : 1,
              pointerEvents: 'none',
            }}
          >
            Button activates once the acknowledgement is selected.
          </span>
        </div>
      </div>
      <style>{`
        @media (max-width:860px) { .path-grid{grid-template-columns:1fr !important} }
        @keyframes cardCascade { from{opacity:0;transform:translateY(28px) scale(.97);filter:blur(6px)} to{opacity:1;transform:none;filter:none} }
        @keyframes rippleOut { from{transform:scale(1);opacity:.8} to{transform:scale(3.5);opacity:0} }
      `}</style>
    </div>
  );
}

