// ─── ROOT ─────────────────────────────────────────────────────────────────────
export default function App() {
  const [screen, setScreen] = useState('statement');
  return (
    <div
      style={{
        minHeight: '100vh',
        fontFamily:
          "Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif",
        color: '#fff',
        overflowX: 'hidden',
        background:
          'linear-gradient(155deg,#003d1f 0%,#00582a 35%,#00723a 60%,#003d1f 100%)',
      }}
    >
      <style>{`
        *{box-sizing:border-box;margin:0;padding:0}
        @keyframes fadeUp{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
        @keyframes pageIn{from{opacity:0;transform:translateY(18px) scale(.986);filter:blur(10px)}to{opacity:1;transform:none;filter:none}}
        @keyframes patternDrift{from{transform:translate3d(0,0,0)}to{transform:translate3d(-4%,-3%,0) rotate(2deg)}}
        @keyframes logoSpin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}
        @keyframes portraitRing{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}
        @keyframes cardShimmer{from{transform:translateX(-100%)}to{transform:translateX(200%)}}
        @keyframes quotePulse{0%,100%{box-shadow:-3px 0 16px -6px rgba(214,161,15,.45)}50%{box-shadow:-3px 0 28px -2px rgba(214,161,15,.8)}}
        ::-webkit-scrollbar{width:6px}::-webkit-scrollbar-track{background:rgba(0,45,22,.5)}::-webkit-scrollbar-thumb{background:rgba(214,161,15,.4);border-radius:3px}
        @media (hover:none){button:active{transform:scale(.96) !important}}
      `}</style>

      {/* Pattern overlay */}
      <div
        style={{
          position: 'fixed',
          inset: '-10%',
          zIndex: 0,
          opacity: 0.14,
          pointerEvents: 'none',
          backgroundImage:
            'radial-gradient(circle at 20px 20px,rgba(255,255,255,.16) 0 5px,transparent 6px),radial-gradient(circle at 68px 58px,rgba(255,255,255,.1) 0 8px,transparent 9px),repeating-radial-gradient(circle at 30% 45%,transparent 0 38px,rgba(0,20,10,.4) 40px 44px,transparent 46px 78px)',
          backgroundSize: '112px 112px,132px 132px,900px 900px',
          animation: 'patternDrift 26s linear infinite',
        }}
      />

      {/* Deep green radial depth accents — never white or pale */}
      <div
        style={{
          position: 'fixed',
          inset: 0,
          zIndex: 0,
          pointerEvents: 'none',
          background:
            'radial-gradient(ellipse at 15% 85%,rgba(0,20,10,.7),transparent 50%), radial-gradient(ellipse at 85% 15%,rgba(0,114,58,.25),transparent 45%)',
        }}
      />

      <Grain />
      <ParticleField />

      <div key={screen} style={{ position: 'relative', zIndex: 2 }}>
        {screen === 'statement' && (
          <StatementScreen onProceed={() => setScreen('register')} />
        )}
        {screen === 'register' && (
          <RegisterTodayScreen
            onParticipate={() => setScreen('participation')}
            onGala={() => setScreen('gala')}
          />
        )}
        {screen === 'participation' && (
          <ParticipationScreen onBack={() => setScreen('register')} />
        )}
        {screen === 'gala' && (
          <GalaScreen onBack={() => setScreen('register')} />
        )}
      </div>
    </div>
  );
}
